// Twelve business menus. Technical capabilities are configured inside their owning pages.
const aiGroups=[{name:'搜索全局配置',keys:['overview','themes','tags','templates']},{name:'数据索引构建',keys:['sources','indexes','indexMonitor']},{name:'智能搜索执行',keys:['search','recommendations']},{name:'运营维护保障',keys:['records','content','operations']}];
aiKeys.splice(0,aiKeys.length,...aiGroups.flatMap(g=>g.keys));
aiPages.splice(0,aiPages.length,'功能概览','搜索主题管理','检索标签管理','主题模板管理','数据源管理','索引管理','索引监控','搜索管理','智能推荐管理','搜索记录管理','搜索内容管理','搜索运营分析');
const aiDescriptions=['了解智能搜索的功能边界、模块关系与使用路径。','统一管理主题配置、发布审核与主题运行情况。','建立层级标签体系，精细标注各类检索对象。','引用、定制并保存通用、行业与专题模板。','配置数据连接，为数据采集与索引构建准备数据源。','集中管理索引配置、映射、采集同步及语义能力。','掌握索引健康、数据完整性、容量与构建任务状态。','配置搜索条件，查看语义检索结果并反馈使用体验。','管理数据产品匹配策略、召回范围与推荐效果。','分析常见、热点、历史和无结果搜索词。','统一管理搜索评价、敏感词和保底回答策略。','分析搜索转化与质量，自动生成所选周期的质量报告。'];
let aiThemePanel='list',aiRecoPanel='matching',aiRecordPanel='history',aiContentPanel='reviews',aiIndexPanel='config';
const aiCollapsed=new Set(['数据索引构建','智能搜索执行','运营维护保障']);
const aiNow=()=>new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).slice(0,16);
const aiTabs=(entries,selected,action)=>`<div class="ais-tabs" role="tablist">${entries.map(([key,name])=>`<button role="tab" aria-selected="${key===selected}" class="${key===selected?'active':''}" onclick="${action}('${key}')">${name}</button>`).join('')}</div>`;
function aiMenuToggle(name){if(aiCollapsed.has(name))aiCollapsed.delete(name);else aiCollapsed.add(name);aiDrawNav();}
function aiDrawNav(){ $('#sidebar').innerHTML=`<div class="ai-nav-title">智能服务系统</div><div class="ais-nav-root">⌕ <b>智能搜索</b><small>4 个模块 · 12 个菜单</small></div>${aiGroups.map(g=>`<button class="ais-group" aria-expanded="${!aiCollapsed.has(g.name)}" onclick="aiMenuToggle('${g.name}')">${g.name}<span>${aiCollapsed.has(g.name)?'›':'⌄'}</span></button>${aiCollapsed.has(g.name)?'':g.keys.map(k=>`<button class="ai-nav-item ${aiTab===k?'active':''}" ${aiReq(k)} onclick="aiOpen('${k}')">${aiPages[aiKeys.indexOf(k)]}</button>`).join('')}`).join('')}<button class="ai-back" onclick="section='launch';render()">⇤ 返回快捷入口</button>`; }
aiOpen=function(tab='overview'){if(tab==='audit'){tab='themes';aiThemePanel='audit';}else if(tab==='stats'){tab='themes';aiThemePanel='stats';}if(!aiKeys.includes(tab))tab='overview';section='intelligent';aiTab=tab;aiGroups.forEach(g=>{if(g.keys.includes(tab))aiCollapsed.delete(g.name);else aiCollapsed.add(g.name);});aiKeyword='';aiStatus='';render();};
aiRender=function(){const i=aiKeys.indexOf(aiTab),group=aiGroups.find(g=>g.keys.includes(aiTab));aiDrawNav();$('#main').innerHTML=`<div class="systemtabs"><span onclick="section='launch';render()">首页</span><span class="selected">智能服务系统</span></div><div class="ai-page" data-req-surface="intelligent.${aiTab}" data-req-page="intelligent-${aiTab}" data-req-title="${aiPages[i]}"><div class="crumb">智能服务系统 / 智能搜索 / ${group.name} / ${aiPages[i]}</div><div class="ai-heading"><div><h1>${aiPages[i]}</h1><p>${aiDescriptions[i]}</p></div><span class="ai-environment">● 原型演示数据</span></div>${aiTab==='themes'?'<div id="ai-theme-tabs"></div>':''}<div id="ai-content"></div></div>`;aiRenderers[aiTab]();};
const aiBaseThemeList=aiThemeList;
aiThemeList=function(){if($('#ai-theme-tabs'))$('#ai-theme-tabs').innerHTML=aiTabs([['list','主题配置'],['audit','发布审核与记录'],['stats','主题运行统计']],aiThemePanel,'aiThemeSwitch');if(aiThemePanel==='audit')aiAuditList();else if(aiThemePanel==='stats')aiStats();else aiBaseThemeList();};
function aiThemeSwitch(panel){aiThemePanel=panel;aiKeyword='';aiStatus='';aiThemeList();}
const aiBaseFilters=aiFilters;
aiFilters=function(statuses,placeholder){if(aiTab==='themes'&&aiThemePanel==='audit')return aiBaseFilters(statuses,placeholder).replace('aiRefresh()','aiAuditList()').replace("aiRefresh()","aiAuditList()");return aiBaseFilters(statuses,placeholder);};
aiRefresh=function(){aiRenderers[aiTab]();};
aiOverview=function(){ $('#ai-content').innerHTML=`<section class="ai-intro" ${aiReq('overview')}><div><span class="ai-kicker">INTELLIGENT SEARCH</span><h2>从资源准备，到智能发现</h2><p>面向本区域参与数据流通利用的企业与个人，统一组织检索主题、数据索引、智能检索与运营管理，支撑数据资源、数据产品及数据业务的智能服务。</p>${aiBtn('配置搜索主题 →',"aiThemePanel='list';aiOpen('themes')",'themes',true)}${aiBtn('体验智能搜索',"aiOpen('search')",'search')}</div><div class="ai-orbit"><span>主题配置</span><b>智能搜索</b><span>数据索引</span><span>运营维护</span><span>搜索执行</span></div></section><section class="panel ai-section" ${aiReq('overview')}><div class="ai-list-head"><h3>四个模块，覆盖完整业务链路</h3><span class="muted">模块可独立进入，无强制操作顺序</span></div><div class="ai-flow">${aiGroups.map((g,i)=>`<button onclick="aiOpen('${g.keys[0]}')"><b>0${i+1}</b><h4>${g.name}</h4><p>${['配置主题、检索标签和模板','接入数据源并构建检索索引','执行检索、返回结果与推荐','维护内容并分析服务质量'][i]}</p><span>进入模块 →</span></button>`).join('')}</div></section><section class="panel ai-section"><h3>功能与使用路径</h3><div class="ais-module-grid">${aiGroups.map((g,i)=>`<article><span class="ais-module-number">0${i+1}</span><h3>${g.name}</h3>${g.keys.map(k=>`<button ${aiReq(k)} onclick="${k==='themes'?"aiThemePanel='list';":''}aiOpen('${k}')"><b>${aiPages[aiKeys.indexOf(k)]}</b><span>${aiDescriptions[aiKeys.indexOf(k)]}</span><i>→</i></button>`).join('')}</article>`).join('')}</div></section>`;};
const aiSources=[{id:11,name:'区域数据资源库',type:'PostgreSQL',host:'10.10.12.8',port:5432,database:'regional_catalog',username:'catalog_reader',status:'连接正常',tested:true},{id:12,name:'数据产品服务库',type:'MySQL',host:'10.10.12.16',port:3306,database:'data_products',username:'product_reader',status:'连接正常',tested:true},{id:13,name:'业务节点接口',type:'HTTP API',host:'https://example.test/api/nodes',port:443,database:'nodes',username:'node_service',status:'未测试',tested:false}];
const aiIndexes=[{id:21,name:'区域资源统一索引',source:11,table:'resource_catalog',status:'正常',documents:18560,capacity:2.4,shards:3,replicas:1,vector:true,dimension:768,mapping:'name→title; description→content; category→tags',semantic:'name=资源名称；description=资源描述；provider_id关联主体表.id',sync:'每日',updated:'2026-11-04 09:00',task:'已完成'},{id:22,name:'数据产品检索索引',source:12,table:'products',status:'更新滞后',documents:8260,capacity:1.2,shards:2,replicas:1,vector:true,dimension:768,mapping:'product_name→title; summary→content',semantic:'product_name=产品名称；supplier_id关联企业表.id',sync:'每小时',updated:'2026-11-03 10:00',task:'待同步'},{id:23,name:'业务节点检索索引',source:13,table:'nodes',status:'索引缺失',documents:0,capacity:0,shards:1,replicas:1,vector:false,dimension:768,mapping:'node_name→title; service→content',semantic:'node_name=业务节点名称；owner_id关联主体表.id',sync:'手动',updated:'—',task:'未构建'}];
const aiIndexTasks=[{name:'区域资源统一索引',type:'全量构建',status:'已完成',count:18560,time:'2026-11-04 09:00'},{name:'数据产品检索索引',type:'增量同步',status:'失败',count:0,time:'2026-11-03 11:00'}];
const aiFormField=(name,label,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const aiBaseUseTemplate=aiUseTemplate;
aiUseTemplate=function(i){aiThemePanel='list';aiBaseUseTemplate(i);};
function aiSourceForm(id=null){const s=aiSources.find(x=>x.id===id)||{};aiModal(id?'编辑数据源':'新增数据源',`<form id="ais-source" ${aiReq('source.configure')} onsubmit="aiSourceSave(event,${id})"><fieldset>${aiFormField('name','数据源名称 *','text',s.name||'','required maxlength="50"')}<label>连接类型 *<select name="type">${aiOptions(['PostgreSQL','MySQL','HTTP API'],s.type)}</select></label>${aiFormField('host','主机地址 / API 地址 *','text',s.host||'','required maxlength="200" placeholder="IP、域名或 https:// 接口地址"')}${aiFormField('port','端口 *','number',s.port||5432,'required min="1" max="65535"')}${aiFormField('database','数据库 / 资源路径 *','text',s.database||'','required maxlength="100"')}${aiFormField('username','连接账号 *','text',s.username||'','required maxlength="100"')}${aiFormField('password','连接凭据（演示输入，不保存）','password','','autocomplete="new-password"')}<div class="notice">本原型仅模拟连接与采集状态，不连接真实数据库。</div></fieldset></form>`,`<button class="btn primary" form="ais-source" ${aiReq('source.save')}>保存</button>`);}
function aiSourceSave(e,id){e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),host=f.get('host').trim();if(!name||!host||!f.get('database').trim()||!f.get('username').trim())return toast('必填字段不能为空白');if(aiSources.some(x=>x.id!==id&&x.name===name))return toast('数据源名称已存在');if(f.get('type')==='HTTP API'&&!/^https:\/\/[^\s]+$/.test(host))return toast('API 地址必须为有效的 HTTPS 地址');if(f.get('type')!=='HTTP API'&&!/^[\w.-]+$/.test(host))return toast('请输入有效的主机名或 IP');const port=Number(f.get('port'));if(!Number.isInteger(port)||port<1||port>65535)return toast('端口必须为1—65535的整数');const data={name,host,type:f.get('type'),port,database:f.get('database').trim(),username:f.get('username').trim(),status:'未测试',tested:false};if(id)Object.assign(aiSources.find(x=>x.id===id),data);else aiSources.push({id:Date.now(),...data});aiClose();aiSourceList();toast('数据源已保存，请测试连接');}
function aiSourceList(){const list=aiSources.filter(x=>x.name.includes(aiKeyword)&&(!aiStatus||x.status===aiStatus));$('#ai-content').innerHTML=`<section class="panel">${aiFilters(['未测试','连接正常','连接失败'])}</section><section class="panel ai-section"><div class="ai-list-head"><h3>数据源列表</h3>${aiBtn('＋ 新增数据源','aiSourceForm()','source.create',true)}</div>${aiTable(['数据源名称','类型','地址','数据库 / 路径','连接状态','操作'],list.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${s.type}</td><td>${esc(s.host)}${s.type==='HTTP API'?'':':'+s.port}</td><td>${esc(s.database)}</td><td>${aiBadge(s.status)}</td><td>${aiLink('连接测试',`aiSourceTest(${s.id})`,'source.test')}${aiLink('编辑',`aiSourceForm(${s.id})`,'source.edit')}${aiLink('删除',`aiSourceDelete(${s.id})`,'source.delete')}</td></tr>`))}</section>`;}
function aiSourceTest(id){const s=aiSources.find(x=>x.id===id);s.tested=!/invalid|fail|unreachable/i.test(s.host);s.status=s.tested?'连接正常':'连接失败';aiSourceList();toast(s.tested?'演示连接测试通过':'演示连接失败，请检查地址与配置');}
function aiSourceDelete(id){if(aiIndexes.some(x=>x.source===id))return toast('该数据源已被索引引用，不能删除');aiConfirm('删除数据源','确认删除该数据源配置？',()=>{aiSources.splice(aiSources.findIndex(x=>x.id===id),1);aiSourceList();toast('数据源已删除');},'source.delete');}
function aiIndexList(){const list=aiIndexes.filter(x=>x.name.includes(aiKeyword)&&(!aiStatus||x.status===aiStatus));$('#ai-content').innerHTML=`<section class="panel">${aiFilters(['正常','更新滞后','索引缺失'])}</section><section class="panel ai-section"><div class="ai-list-head"><h3>索引列表</h3>${aiBtn('＋ 创建索引','aiIndexForm()','index.create',true)}</div>${aiTable(['索引名称','数据源','文档数','容量','语义向量化','状态','操作'],list.map(x=>`<tr><td><b>${esc(x.name)}</b><small class="ai-cell-sub">最近同步 ${x.updated}</small></td><td>${esc(aiSources.find(s=>s.id===x.source)?.name||'—')}</td><td>${x.documents.toLocaleString()}</td><td>${x.capacity} GB</td><td>${x.vector?'已启用 · '+x.dimension+' 维':'未启用'}</td><td>${aiBadge(x.status)}</td><td>${aiLink('配置详情',`aiIndexDetail(${x.id})`,'index.configure')}${aiLink('采集同步',`aiIndexSync(${x.id})`,'index.sync')}${aiLink('删除',`aiIndexDelete(${x.id})`,'index.delete')}</td></tr>`))}</section>`;}
function aiIndexForm(id=null){const x=aiIndexes.find(x=>x.id===id)||{};aiModal(id?'编辑索引配置':'创建索引',`<form id="ais-index" ${aiReq('index.configure')} onsubmit="aiIndexSave(event,${id})"><fieldset>${aiFormField('name','索引名称 *','text',x.name||'','required maxlength="50"')}<label>数据源 *<select name="source" required>${aiSources.map(s=>`<option value="${s.id}" ${s.id===x.source?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${aiFormField('table','采集表 / 资源路径 *','text',x.table||'','required maxlength="100"')}<label>字段映射 *<textarea name="mapping" required maxlength="1000" placeholder="源字段→目标字段；如 name→title">${esc(x.mapping||'name→title; description→content')}</textarea></label><label>采集同步策略<select name="sync">${aiOptions(['手动','每小时','每日'],x.sync||'手动')}</select></label><label>语义向量化<select name="vector"><option value="true" ${x.vector?'selected':''}>启用</option><option value="false" ${!x.vector?'selected':''}>关闭</option></select></label>${aiFormField('dimension','向量维度','number',x.dimension||768,'required min="64" max="4096"')}${aiFormField('shards','索引分片数 *','number',x.shards||1,'required min="1" max="16"')}${aiFormField('replicas','副本数 *','number',x.replicas??1,'required min="0" max="3"')}<div class="notice">分片、副本与向量化属于本页配置；保存后需采集同步才能更新索引。</div></fieldset></form>`,`<button class="btn primary" form="ais-index" ${aiReq('index.save')}>保存配置</button>`);}
function aiIndexSave(e,id){e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),mapping=f.get('mapping').trim();if(!name||!f.get('table').trim()||!mapping.includes('→'))return toast('请输入名称、采集表和有效的字段映射（源字段→目标字段）');if(aiIndexes.some(x=>x.id!==id&&x.name===name))return toast('索引名称已存在');const x={name,source:Number(f.get('source')),table:f.get('table').trim(),mapping,sync:f.get('sync'),vector:f.get('vector')==='true',dimension:Number(f.get('dimension')),shards:Number(f.get('shards')),replicas:Number(f.get('replicas'))};if(!aiSources.some(s=>s.id===x.source)||!Number.isInteger(x.shards)||x.shards<1||x.shards>16||!Number.isInteger(x.replicas)||x.replicas<0||x.replicas>3||!Number.isInteger(x.dimension)||x.dimension<64||x.dimension>4096)return toast('请检查数据源、分片、副本和向量维度配置');if(id)Object.assign(aiIndexes.find(t=>t.id===id),x,{status:'更新滞后',task:'待同步'});else aiIndexes.push({id:Date.now(),...x,status:'索引缺失',task:'未构建',documents:0,capacity:0,updated:'—',semantic:'尚未解析'});aiClose();aiIndexList();toast('索引配置已保存');}
function aiIndexDetail(id,panel='config'){const x=aiIndexes.find(x=>x.id===id);aiModal('索引配置详情 · '+x.name,`${aiTabs([['config','配置详情'],['mapping','数据映射'],['semantic','语义解析与关联查询'],['sync','采集与构建状态']],panel,`aiIndexDetail.bind(null,${id})`)}${panel==='config'?`<dl class="ais-detail"><dt>数据源</dt><dd>${esc(aiSources.find(s=>s.id===x.source)?.name)}</dd><dt>采集表</dt><dd>${esc(x.table)}</dd><dt>分片 / 副本</dt><dd>${x.shards} 分片 / ${x.replicas} 副本</dd><dt>语义向量化</dt><dd>${x.vector?'启用 · '+x.dimension+' 维':'关闭'}</dd><dt>同步策略</dt><dd>${x.sync}</dd></dl>`:panel==='mapping'?`<h3>源字段 → 检索字段</h3><pre class="ais-code">${esc(x.mapping.split(';').join('\n'))}</pre>`:panel==='semantic'?`<p class="muted">解析库表字段含义与关联关系，为语义检索提供结构化依据。</p><pre class="ais-code">${esc(x.semantic)}</pre>${aiBtn('执行语义解析',`aiIndexParse(${id})`,'index.semantic',true)}<form class="ais-inline-form" ${aiReq('index.relations')} onsubmit="event.preventDefault();aiIndexRelation(${id},this.keyword.value)"><input name="keyword" required maxlength="50" placeholder="输入字段或关联表名称"><button class="btn">关联查询</button></form><div id="ais-relations"></div>`:`<p>最近同步：${x.updated}</p><p>构建状态：${x.task}</p><p>已索引文档：${x.documents.toLocaleString()}</p><p>向量状态：${x.vector&&x.documents?'已向量化':'尚未向量化'}</p>${aiBtn('采集同步',`aiClose();aiIndexSync(${id})`,'index.sync',true)}`}`,`${aiBtn('编辑配置',`aiIndexForm(${id})`,'index.edit')}`);}
function aiIndexParse(id){const x=aiIndexes.find(x=>x.id===id);x.semantic=x.mapping.split(';').map(v=>v.trim()).filter(Boolean).map(v=>v.split('→')[0]+' = '+({'title':'名称字段','content':'描述字段','tags':'分类标签'}[v.split('→')[1]]||'业务属性')).join('\n')+'\nprovider_id → 主体表.id（关联键，演示）';aiIndexDetail(id,'semantic');toast('字段语义与关系解析完成（演示）');}
function aiIndexRelation(id,keyword){const x=aiIndexes.find(x=>x.id===id),q=keyword.trim();if(!q)return toast('请输入查询关键词');const lines=x.semantic.split(/[；\n]/).filter(s=>s.toLowerCase().includes(q.toLowerCase()));$('#ais-relations').innerHTML=lines.length?`<pre class="ais-code">${esc(lines.join('\n'))}</pre>`:'<p class="muted">暂无匹配的语义字段或关联关系</p>';}
function aiIndexSync(id){const x=aiIndexes.find(x=>x.id===id),s=aiSources.find(s=>s.id===x.source);if(!s?.tested)return toast('请先到数据源管理完成连接测试');aiConfirm('采集同步','将按已保存映射采集样例数据，并更新索引与向量状态。',()=>{x.status='正常';x.task='已完成';x.documents=x.documents||1240;x.capacity=x.capacity||0.18;x.updated=aiNow();aiIndexTasks.unshift({name:x.name,type:'采集同步',status:'已完成',count:x.documents,time:x.updated});aiIndexList();toast(x.vector?'演示采集、索引与向量化任务已完成':'演示采集与索引任务已完成');},'index.sync');}
function aiIndexDelete(id){aiConfirm('删除索引','确认删除索引及其演示数据？数据源配置将保留。',()=>{aiIndexes.splice(aiIndexes.findIndex(x=>x.id===id),1);aiIndexList();toast('索引已删除');},'index.delete');}
function aiIndexHealth(){const now=Date.now();aiIndexes.forEach(x=>{if(!x.documents)x.status='索引缺失';else if(x.sync!=='手动'&&now-new Date(x.updated.replace(' ','T')+'+08:00').getTime()>(x.sync==='每日'?24:1)*3600000)x.status='更新滞后';else x.status='正常';});aiIndexMonitor();toast('健康检测完成：已核对文档、同步周期与更新时间');}
function aiIndexMonitor(){const warnings=aiIndexes.filter(x=>x.status!=='正常');$('#ai-content').innerHTML=`<div class="ais-toolbar">${aiBtn('↻ 索引健康检测',"aiIndexHealth()",'index.health',true)}</div><div class="ai-metrics" ${aiReq('index.monitor.metrics')}>${aiMetric('健康索引',aiIndexes.filter(x=>x.status==='正常').length,'配置有效且同步正常')}${aiMetric('异常预警',warnings.length,'索引缺失或更新滞后')}${aiMetric('索引总容量',aiIndexes.reduce((s,x)=>s+x.capacity,0).toFixed(2)+' GB','当前主索引占用量，不含副本')}${aiMetric('构建任务',aiIndexTasks.length,'累计演示构建与同步任务')}</div><section class="panel ai-section" ${aiReq('index.monitor.alerts')}><h3>索引预警</h3>${aiTable(['索引','预警类型','检测依据','最近更新时间','处理'],warnings.map(x=>`<tr><td>${esc(x.name)}</td><td>${aiBadge(x.status)}</td><td>${x.status==='索引缺失'?'尚未构建可用索引':'已超过设定同步周期'}</td><td>${x.updated}</td><td>${aiLink('前往索引管理',"aiOpen('indexes')",'indexes')}</td></tr>`))}</section><section class="panel ai-section" ${aiReq('index.monitor.tasks')}><h3>构建任务统计与记录</h3><p class="muted">完成 ${aiIndexTasks.filter(x=>x.status==='已完成').length}　失败 ${aiIndexTasks.filter(x=>x.status==='失败').length}</p>${aiTable(['索引','任务类型','状态','处理文档','时间'],aiIndexTasks.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.type}</td><td>${aiBadge(x.status)}</td><td>${x.count.toLocaleString()}</td><td>${x.time}</td></tr>`))}</section>`;}
const aiSearchCatalog=[{id:31,name:'区域交通运行数据集',type:'数据资源',tags:['交通运输','公共数据'],desc:'覆盖道路通行、交通流量与公共交通运行数据。',owner:'区域交通数据中心',index:21},{id:32,name:'交通物流数据分析产品',type:'数据产品',tags:['交通运输'],desc:'为物流运输提供线路、流量与运力分析。',owner:'区域物流运营中心',index:22},{id:33,name:'企业信用评估产品',type:'数据产品',tags:['金融服务','企业数据'],desc:'提供企业经营、信用及金融风险评估指标。',owner:'区域金融服务中心',index:22},{id:34,name:'城市公共服务数据集',type:'数据资源',tags:['公共数据'],desc:'汇聚城市治理及公共服务基础数据。',owner:'城市数据中心',index:21},{id:35,name:'区域产业数据协同节点',type:'业务节点',tags:['企业数据'],desc:'提供产业数据资源发现与企业协同服务。',owner:'区域产业运营中心',index:21},{id:36,name:'区域数据服务企业',type:'接入主体',tags:['企业数据'],desc:'参与区域数据流通利用的可信接入主体。',owner:'区域数据服务有限公司',index:21},{id:37,name:'城市物流运力数据',type:'数据资源',tags:['交通运输'],desc:'包含物流运力、配送线路及车辆运行信息。',owner:'城市交通中心',index:21}];
