function aiSearchPage(){const s=aiSearchState,published=aiThemes.filter(t=>t.status==='已发布');if(!published.some(t=>t.id===s.theme))s.theme=published[0]?.id;$('#ai-content').innerHTML=`<section class="panel ai-section" ${aiReq('search.configure')}><form id="ais-search" onsubmit="aiExecuteSearch(event)"><div class="ais-search-box"><span>⌕</span><input name="keyword" required maxlength="100" value="${esc(s.keyword)}" placeholder="输入资源、产品或业务需求，如：交通物流数据"> <button class="btn primary" ${aiReq('search.execute')}>智能搜索</button></div><div class="ais-search-options"><label>搜索主题<select name="theme" required>${published.map(t=>`<option value="${t.id}" ${s.theme===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>检索范围<select name="scope">${aiOptions(['全部',...aiObjects],s.scope)}</select></label><label>搜索方式<select name="method">${aiOptions(['语义检索','关键词检索'],s.method)}</select></label><label>排序方式<select name="ranking">${aiOptions(['知识相关性','名称排序'],s.ranking)}</select></label></div><details class="ais-advanced" open><summary>自定义搜索参数</summary><div class="ai-checks">${[['fuzzy','模糊匹配'],['rewrite','查询改写'],['intent','意图识别'],['personal','个性化结果']].map(([k,n])=>`<label><input type="checkbox" name="${k}" ${s[k]?'checked':''}>${n}</label>`).join('')}</div><p class="muted">语义匹配、意图识别与知识排序在当前表单统一配置。个性化按当前用户的交通运输偏好演示。</p></details></form></section><div id="ais-search-results"></div>`;aiSearchResults();}
function aiExecuteSearch(e){e.preventDefault();const f=new FormData(e.target),s=aiSearchState,q=f.get('keyword').trim();if(!q)return toast('请输入搜索关键词');Object.assign(s,{keyword:q,theme:Number(f.get('theme')),scope:f.get('scope'),method:f.get('method'),ranking:f.get('ranking'),fuzzy:f.has('fuzzy'),rewrite:f.has('rewrite'),intent:f.has('intent'),personal:f.has('personal'),page:1,blocked:false});const theme=aiThemes.find(t=>t.id===s.theme&&t.status==='已发布');if(!theme)return toast('请选择有效的已发布主题');const sensitive=aiSensitiveWords.filter(w=>w.status==='启用'&&q.includes(w.word));s.blocked=sensitive.length>0;sensitive.forEach(w=>w.hits++);const rewritten=s.rewrite?q.replace(/交痛/g,'交通').replace(/物留/g,'物流'):q;s.rewritten=rewritten;s.intentLabel=/交通|物流|运力/.test(rewritten)?'交通物流资源发现':/信用|金融|企业/.test(rewritten)?'企业与金融数据检索':'通用资源检索';let terms=rewritten.toLowerCase().split(/[\s，,]+/).filter(Boolean);if(s.method==='语义检索'){if(/交通|物流|运输/.test(rewritten))terms.push('交通','物流','运力');if(/企业|信用|金融/.test(rewritten))terms.push('企业','信用','金融');if(/城市|公共|治理/.test(rewritten))terms.push('城市','公共');}if(s.fuzzy&&terms.every(t=>t.length>2))terms.push(...terms.map(t=>t.slice(0,2)));s.results=s.blocked?[]:aiSearchCatalog.filter(x=>theme.objects.includes(x.type)&&(s.scope==='全部'||x.type===s.scope)&&aiIndexes.some(i=>i.id===x.index&&i.status!=='索引缺失')).map(x=>({...x,score:terms.reduce((n,t)=>n+(x.name.toLowerCase().includes(t)?3:0)+(x.desc.toLowerCase().includes(t)?1:0)+(x.tags.some(v=>v.includes(t))?2:0),0)+(s.personal&&x.tags.includes('交通运输')?2:0)})).filter(x=>x.score>0).sort((a,b)=>s.ranking==='名称排序'?a.name.localeCompare(b.name,'zh-CN'):b.score-a.score);aiSearchLogs.unshift({id:Date.now(),keyword:q,count:1,hits:s.results.length,time:aiNow(),user:'当前用户',duration:118,blocked:s.blocked});aiSearchPage();}
function aiSearchResults(){const s=aiSearchState;if(s.results===null){$('#ais-search-results').innerHTML=`<section class="panel ais-search-empty"><div>⌕</div><h3>输入需求，发现区域数据价值</h3><p>按主题、范围与检索方式发起搜索，结果支持分页和点赞点踩。</p><p>可试试：交通物流、企业信用、公共数据</p></section>`;return;}const size=3,total=s.results.length,max=Math.max(1,Math.ceil(total/size));s.page=Math.min(s.page,max);const list=s.results.slice((s.page-1)*size,s.page*size);const shouldFallback=aiFallback.enabled&&(s.blocked?aiFallback.trigger!=='仅无结果':aiFallback.trigger!=='仅敏感词命中');$('#ais-search-results').innerHTML=`<div class="ais-result-summary" ${aiReq('search.analysis')}><b>搜索结果 ${total} 条</b><span>${s.blocked?'敏感词命中，已拦截':`查询：${esc(s.keyword)}${s.rewritten!==s.keyword?' → '+esc(s.rewritten):''}`}</span>${s.intent?`<span>识别意图：${esc(s.intentLabel)}</span>`:''}<small>示例响应 118 ms</small></div>${list.length?list.map(x=>`<article class="panel ais-result" ${aiReq('search.results')}><div><span class="ai-badge">${x.type}</span><small>${esc(x.owner)}</small></div><h3>${aiLink(esc(x.name),`aiSearchDetail(${x.id})`,'search.detail')}</h3><p>${esc(x.desc)}</p><div class="ais-result-footer"><span>${x.tags.map(t=>`<i>${esc(t)}</i>`).join('')}</span><div>${aiLink(aiVotes[x.id]==='点赞'?'已赞':'赞',`aiVote(${x.id},'点赞')`,'search.feedback')}${aiLink(aiVotes[x.id]==='点踩'?'已踩':'踩',`aiVote(${x.id},'点踩')`,'search.feedback')}</div></div></article>`).join(''):`<section class="panel ais-search-empty" ${aiReq('content.fallback')}><h3>${s.blocked?'搜索内容已拦截':'暂无匹配结果'}</h3><p>${esc(shouldFallback?(s.blocked?aiFallback.sensitiveText:aiFallback.text):'请调整搜索条件后重试。')}</p></section>`}${total?`<div class="ais-pagination" ${aiReq('search.pagination')}><span>共 ${total} 条 · 每页 ${size} 条</span><button class="btn" ${s.page===1?'disabled':''} onclick="aiSearchState.page--;aiSearchResults()">上一页</button><b>${s.page} / ${max}</b><button class="btn" ${s.page===max?'disabled':''} onclick="aiSearchState.page++;aiSearchResults()">下一页</button></div>`:''}`;}
function aiSearchDetail(id){const x=aiSearchCatalog.find(x=>x.id===id);aiRecoEvents.push({id,type:'click',time:aiNow()});aiModal('检索对象详情',`<h3>${esc(x.name)}</h3><p>${esc(x.desc)}</p><dl class="ais-detail"><dt>对象类型</dt><dd>${x.type}</dd><dt>提供方</dt><dd>${esc(x.owner)}</dd><dt>标签</dt><dd>${x.tags.join('、')}</dd></dl>`);}
function aiVote(id,rating){const x=aiSearchCatalog.find(x=>x.id===id);aiVotes[id]=rating;let row=aiSearchReviews.find(r=>r.result===x.name&&r.keyword===aiSearchState.keyword&&r.user==='当前用户');if(row)Object.assign(row,{rating,time:aiNow(),status:'待处理'});else aiSearchReviews.unshift({id:Date.now(),keyword:aiSearchState.keyword,result:x.name,rating,comment:'',time:aiNow(),status:'待处理',user:'当前用户'});aiSearchResults();toast('评价已记录，可在搜索内容管理中查看');}
function aiRecoSwitch(panel){aiRecoPanel=panel;aiRecoPage();}
function aiRecoPage(){const c=aiRecoConfig;$('#ai-content').innerHTML=`${aiTabs([['matching','标签分析与匹配'],['strategy','推荐策略配置'],['effect','推荐效果统计']],aiRecoPanel,'aiRecoSwitch')}<div id="ais-reco-panel"></div>`;if(aiRecoPanel==='strategy'){ $('#ais-reco-panel').innerHTML=`<section class="panel ai-section"><h3>推荐策略</h3><form id="ais-reco-config" ${aiReq('recommendation.configure')} onsubmit="aiRecoSave(event)"><fieldset class="ais-config-form"><label>推荐策略<select name="strategy">${aiOptions(['标签匹配','标签与热度融合'],c.strategy)}</select></label><label>启用推荐<select name="enabled"><option value="true" ${c.enabled?'selected':''}>启用</option><option value="false" ${!c.enabled?'selected':''}>停用</option></select></label>${aiFormField('supply','供方标签权重（%） *','number',c.supply,'required min="0" max="100"')}${aiFormField('demand','需方标签权重（%） *','number',c.demand,'required min="0" max="100"')}<label>召回范围<select name="scope">${aiOptions(['已发布数据产品','当前主题的数据产品'],c.scope)}</select></label><label class="ais-full">推荐白名单<div class="ai-checks">${aiSearchCatalog.filter(x=>x.type==='数据产品').map(x=>`<label><input type="checkbox" name="whitelist" value="${esc(x.name)}" ${c.whitelist.includes(x.name)?'checked':''}>${esc(x.name)}</label>`).join('')}</div><small class="muted">白名单仅在召回范围内优先推荐，不绕过数据访问权限。</small></label><div class="ais-full notice">供方与需方权重之和必须为100%。策略保存后应用于本页下一次匹配。</div><button class="btn primary" ${aiReq('recommendation.save')}>保存策略</button></fieldset></form></section>`;return;}if(aiRecoPanel==='effect'){const exposures=aiRecoEvents.filter(x=>x.type==='exposure').length,clicks=aiRecoEvents.filter(x=>x.type==='recommendation-click').length;$('#ais-reco-panel').innerHTML=`<div class="ai-metrics" ${aiReq('recommendation.metrics')}>${aiMetric('推荐曝光',exposures,'本轮匹配展示次数')}${aiMetric('推荐点击',clicks,'推荐详情点击次数')}${aiMetric('推荐点击率',exposures?(clicks/exposures*100).toFixed(1)+'%':'0%','点击次数 / 曝光次数')}${aiMetric('白名单产品',c.whitelist.length,'当前策略配置数量')}</div><section class="panel ai-section"><h3>产品推荐效果</h3>${aiTable(['产品','曝光次数','点击次数'],aiSearchCatalog.filter(x=>x.type==='数据产品').map(x=>`<tr><td>${esc(x.name)}</td><td>${aiRecoEvents.filter(e=>e.id===x.id&&e.type==='exposure').length}</td><td>${aiRecoEvents.filter(e=>e.id===x.id&&e.type==='recommendation-click').length}</td></tr>`))}<p class="muted">范围为当前原型会话，匹配成功时记曝光，点击推荐详情时记点击；进入本页刷新。</p></section>`;return;}$('#ais-reco-panel').innerHTML=`<section class="panel ai-section" ${aiReq('recommendation.match')}><h3>供需标签分析与数据产品推荐</h3><form onsubmit="aiMatchProducts(event)"><div class="ais-search-options"><label>需方主体<select name="buyer"><option>区域物流企业</option><option>区域金融企业</option></select></label><label>需求标签<select name="tag"><option>交通运输</option><option>金融服务</option><option>企业数据</option></select></label><label>搜索主题<select name="theme">${aiThemes.filter(t=>t.status==='已发布').map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><button class="btn primary">分析并匹配</button></div></form><p class="muted">当前策略：${c.strategy} · 供方 ${c.supply}% / 需方 ${c.demand}% · ${c.scope}</p></section><div id="ais-reco-results"><section class="panel ais-search-empty"><h3>选择主体与需求标签，获取匹配产品</h3><p>推荐按标签匹配得分排序，并应用召回范围及白名单配置。</p></section></div>`;}
function aiRecoSave(e){e.preventDefault();const f=new FormData(e.target),s=Number(f.get('supply')),d=Number(f.get('demand'));if(!Number.isInteger(s)||!Number.isInteger(d)||s<0||d<0||s+d!==100)return toast('供需权重需为0—100整数，且合计100%');Object.assign(aiRecoConfig,{strategy:f.get('strategy'),supply:s,demand:d,scope:f.get('scope'),whitelist:f.getAll('whitelist'),enabled:f.get('enabled')==='true'});toast('推荐策略已保存');}
function aiMatchProducts(e){e.preventDefault();if(!aiRecoConfig.enabled)return toast('推荐已停用，请先启用策略');const f=new FormData(e.target),tag=f.get('tag'),theme=aiThemes.find(x=>x.id===Number(f.get('theme'))),buyerTag=f.get('buyer')==='区域物流企业'?'交通运输':'金融服务';if(!theme)return toast('请选择已发布主题');const c=aiRecoConfig;const list=aiSearchCatalog.filter(x=>x.type==='数据产品'&&(c.scope!=='当前主题的数据产品'||(theme.objects.includes('数据产品')&&(!theme.tags.length||theme.tags.some(t=>x.tags.includes(t)))))).map(x=>({...x,score:(x.tags.includes(tag)?c.demand:0)+(x.tags.includes(buyerTag)?c.supply:0)+(c.strategy==='标签与热度融合'?5:0),white:c.whitelist.includes(x.name)})).filter(x=>x.score>0||x.white).sort((a,b)=>Number(b.white)-Number(a.white)||b.score-a.score);list.forEach(x=>aiRecoEvents.push({id:x.id,type:'exposure',time:aiNow()}));$('#ais-reco-results').innerHTML=`<section class="panel ai-section" ${aiReq('recommendation.results')}><h3>匹配结果 ${list.length} 条</h3><p class="muted">需方：${esc(f.get('buyer'))} · 主体标签：${buyerTag} · 需求标签：${tag}</p>${aiTable(['推荐产品','供方标签','匹配得分','推荐依据','操作'],list.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.tags.join('、')}</td><td>${x.score}</td><td>${x.white?'白名单优先；':''}供需标签加权${c.strategy==='标签与热度融合'?'＋热度':''}</td><td>${aiLink('查看产品',`aiRecoDetail(${x.id})`,'recommendation.detail')}</td></tr>`))}</section>`;}
function aiRecoDetail(id){aiRecoEvents.push({id,type:'recommendation-click',time:aiNow()});aiSearchDetail(id);}
function aiRecordSwitch(panel){aiRecordPanel=panel;aiKeyword='';aiStatus='';aiRecordPage();}
function aiRecordPage(){const cutoff=new Date(Date.now()-6*86400000).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});const all=aiSearchLogs.filter(x=>x.keyword.includes(aiKeyword)&&(aiRecordPanel!=='hot'||x.time.slice(0,10)>=cutoff)),grouped=new Map();all.forEach(x=>{if(aiRecordPanel==='noresults'&&(x.hits!==0||x.blocked))return;const g=grouped.get(x.keyword)||{keyword:x.keyword,count:0,last:x.time};g.count+=x.count;if(x.time>g.last)g.last=x.time;grouped.set(x.keyword,g);});const summary=[...grouped.values()].sort((a,b)=>b.count-a.count);$('#ai-content').innerHTML=`${aiTabs([['history','搜索历史'],['common','常见搜索'],['hot','热点搜索'],['noresults','无结果搜索词']],aiRecordPanel,'aiRecordSwitch')}<section class="panel">${aiFilters([],'请输入搜索词')}</section><section class="panel ai-section" ${aiReq('records.query')}><h3>${{history:'搜索历史记录',common:'常见搜索词',hot:'热点搜索词',noresults:'无结果搜索词统计'}[aiRecordPanel]}</h3><p class="muted">${{history:'当前区域的搜索请求与样例历史记录，按时间倒序展示。',common:'按全部已记录请求次数降序统计。',hot:'最近7日搜索请求，按搜索词调用次数降序排名。',noresults:'仅统计返回0条结果且未被敏感词拦截的搜索请求。'}[aiRecordPanel]}</p>${aiRecordPanel==='history'?aiTable(['搜索词','使用主体','结果数','状态','响应时间','搜索时间'],all.map(x=>`<tr><td>${esc(x.keyword)}</td><td>${esc(x.user)}</td><td>${x.hits}</td><td>${x.blocked?'已拦截':x.hits?'有结果':'无结果'}</td><td>${x.duration} ms</td><td>${x.time}</td></tr>`)):aiTable(['排名','搜索词','搜索次数','最近搜索时间'],summary.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.keyword)}</td><td>${x.count}</td><td>${x.last}</td></tr>`))}</section>`;}
function aiContentSwitch(panel){aiContentPanel=panel;aiKeyword='';aiStatus='';aiContentPage();}
function aiContentPage(){ $('#ai-content').innerHTML=aiTabs([['reviews','搜索评价'],['sensitive','敏感词管理'],['fallback','保底回答与策略']],aiContentPanel,'aiContentSwitch')+'<div id="ais-content-panel"></div>';if(aiContentPanel==='reviews'){const list=aiSearchReviews.filter(x=>(x.keyword+x.result).includes(aiKeyword)&&(!aiStatus||x.status===aiStatus));$('#ais-content-panel').innerHTML=`<section class="panel">${aiFilters(['待处理','已处理'])}</section><section class="panel ai-section" ${aiReq('content.reviews')}><h3>搜索评价管理</h3>${aiTable(['搜索词','评价对象','评价','反馈说明','时间','处理状态','操作'],list.map(x=>`<tr><td>${esc(x.keyword)}</td><td>${esc(x.result)}</td><td>${aiBadge(x.rating)}</td><td>${esc(x.comment||'—')}</td><td>${x.time}</td><td>${x.status}</td><td>${aiLink('查看 / 处理',`aiReviewFeedback(${x.id})`,'content.review.handle')}</td></tr>`))}</section>`;return;}if(aiContentPanel==='sensitive'){const list=aiSensitiveWords.filter(x=>x.word.includes(aiKeyword)&&(!aiStatus||x.status===aiStatus));$('#ais-content-panel').innerHTML=`<div class="ai-metrics" ${aiReq('content.sensitive.metrics')}>${aiMetric('敏感词',aiSensitiveWords.length,'当前词库总量')}${aiMetric('启用词',aiSensitiveWords.filter(x=>x.status==='启用').length,'参与搜索拦截')}${aiMetric('累计命中',aiSensitiveWords.reduce((s,x)=>s+x.hits,0),'按每次搜索命中的词计数')}${aiMetric('停用词',aiSensitiveWords.filter(x=>x.status==='停用').length,'保留历史命中记录')}</div><section class="panel">${aiFilters(['启用','停用'])}</section><section class="panel ai-section"><div class="ai-list-head"><h3>敏感词库与命中统计</h3><div>${aiBtn('＋ 新增敏感词','aiSensitiveForm()','content.sensitive.create',true)} <label class="btn ais-upload" ${aiReq('content.sensitive.import')}>批量导入<input type="file" accept=".csv,.txt" hidden onchange="aiSensitiveImport(this)"></label></div></div><p class="muted">导入格式：UTF-8 CSV / TXT，每行“敏感词,分类”，可含表头；最多1000行，文件不超过1MB。</p>${aiTable(['敏感词','分类','状态','命中次数','操作'],list.map(x=>`<tr><td>${esc(x.word)}</td><td>${esc(x.category)}</td><td>${aiBadge(x.status)}</td><td>${x.hits}</td><td>${aiLink('编辑',`aiSensitiveForm(${x.id})`,'content.sensitive.edit')}${aiLink(x.status==='启用'?'停用':'启用',`aiSensitiveToggle(${x.id})`,'content.sensitive.toggle')}</td></tr>`))}</section>`;return;}const c=aiFallback;$('#ais-content-panel').innerHTML=`<section class="panel ai-section"><h3>保底回答与触发策略</h3><form ${aiReq('content.fallback')} onsubmit="aiFallbackSave(event)"><fieldset class="ais-config-form"><label>策略状态<select name="enabled"><option value="true" ${c.enabled?'selected':''}>启用</option><option value="false" ${!c.enabled?'selected':''}>停用</option></select></label><label>触发条件<select name="trigger">${aiOptions(['无结果与敏感词命中','仅无结果','仅敏感词命中'],c.trigger)}</select></label><label class="ais-full">无结果保底回答 *<textarea name="text" required maxlength="300">${esc(c.text)}</textarea></label><label class="ais-full">敏感词命中回答 *<textarea name="sensitiveText" required maxlength="300">${esc(c.sensitiveText)}</textarea></label><p class="notice ais-full">敏感词始终执行拦截；保底回答策略仅控制展示文案，不解除拦截。</p><button class="btn primary" ${aiReq('content.fallback.save')}>保存策略</button></fieldset></form></section>`;}
function aiReviewFeedback(id){const x=aiSearchReviews.find(x=>x.id===id);aiModal('搜索评价处理',`<p>检索词：${esc(x.keyword)}</p><p>评价对象：${esc(x.result)}</p><p>评价：${x.rating}　${esc(x.comment||'无补充说明')}</p><form id="ais-feedback" ${aiReq('content.review.handle')} onsubmit="event.preventDefault();const note=this.note.value.trim();if(!note)return toast('请填写处理说明');Object.assign(aiSearchReviews.find(x=>x.id===${id}),{status:'已处理',note});aiClose();aiContentPage();toast('评价处理记录已保存')"><fieldset><label>处理说明 *<textarea name="note" required maxlength="300">${esc(x.note||'')}</textarea></label></fieldset></form>`,`<button class="btn primary" form="ais-feedback" ${aiReq('content.review.save')}>保存处理</button>`);}
function aiSensitiveForm(id=null){const x=aiSensitiveWords.find(x=>x.id===id)||{};aiModal(id?'编辑敏感词':'新增敏感词',`<form id="ais-sensitive" ${aiReq('content.sensitive.configure')} onsubmit="aiSensitiveSave(event,${id})"><fieldset>${aiFormField('word','敏感词 *','text',x.word||'','required maxlength="50"')}${aiFormField('category','分类 *','text',x.category||'违规内容','required maxlength="30"')}</fieldset></form>`,`<button class="btn primary" form="ais-sensitive">保存</button>`);}
function aiSensitiveSave(e,id){e.preventDefault();const f=new FormData(e.target),word=f.get('word').trim(),category=f.get('category').trim();if(!word||!category)return toast('敏感词与分类不能为空白');if(aiSensitiveWords.some(x=>x.id!==id&&x.word===word))return toast('敏感词已存在');if(id)Object.assign(aiSensitiveWords.find(x=>x.id===id),{word,category});else aiSensitiveWords.push({id:Date.now(),word,category,status:'启用',hits:0});aiClose();aiContentPage();toast('敏感词已保存');}
function aiSensitiveToggle(id){const x=aiSensitiveWords.find(x=>x.id===id);aiConfirm(x.status==='启用'?'停用敏感词':'启用敏感词','确认调整该词的搜索拦截状态？',()=>{x.status=x.status==='启用'?'停用':'启用';aiContentPage();toast('词库状态已更新');},'content.sensitive.toggle');}
function aiParseSensitive(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length-(lines[0]?.split(',')[0].trim()==='敏感词'?1:0)>1000)throw Error('最多导入1000行');const seen=new Set(aiSensitiveWords.map(x=>x.word)),added=[];let skipped=0;for(const [i,line] of lines.entries()){const parts=line.split(',').map(x=>x.trim());if(i===0&&parts[0]==='敏感词')continue;if(parts.length!==2||!parts[0]||parts[0].length>50||!parts[1]||parts[1].length>30)throw Error('第'+(i+1)+'行格式无效，请使用“敏感词,分类”');if(seen.has(parts[0])){skipped++;continue;}seen.add(parts[0]);added.push({id:Date.now()+i,word:parts[0],category:parts[1],status:'启用',hits:0});}return {added,skipped};}
async function aiSensitiveImport(input){const file=input.files[0];if(!file)return;if(!/\.(csv|txt)$/i.test(file.name)||file.size>1024*1024){input.value='';return toast('请选择不超过1MB的CSV或TXT文件');}try{const text=await file.text(),result=aiParseSensitive(text);if(!result.added.length)return toast('未发现新增词，重复条目已跳过');aiSensitiveWords.push(...result.added);aiContentPage();toast(`导入成功 ${result.added.length} 条，重复跳过 ${result.skipped} 条`);}catch(e){toast(e.message||'文件读取失败');}finally{input.value='';}}
function aiFallbackSave(e){e.preventDefault();const f=new FormData(e.target);if(!f.get('text').trim()||!f.get('sensitiveText').trim())return toast('保底回答不能为空白');Object.assign(aiFallback,{enabled:f.get('enabled')==='true',trigger:f.get('trigger'),text:f.get('text').trim(),sensitiveText:f.get('sensitiveText').trim()});toast('保底回答策略已保存');}
let aiOperationRange=7,aiQualityReport=null;
function aiOperationData(){const start=new Date();start.setUTCDate(start.getUTCDate()-(aiOperationRange-1));const cutoff=start.toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});const logs=aiSearchLogs.filter(x=>x.time.slice(0,10)>=cutoff);const searches=logs.reduce((s,x)=>s+x.count,0),noresults=logs.filter(x=>x.hits===0&&!x.blocked).reduce((s,x)=>s+x.count,0),blocked=logs.filter(x=>x.blocked).reduce((s,x)=>s+x.count,0);const clicks=Math.min(searches-noresults-blocked,Math.round((searches-noresults-blocked)*.68)+aiRecoEvents.filter(x=>x.type==='click').length);return {searches,noresults,blocked,clicks,results:searches-noresults-blocked,logs,cutoff};}
function aiOperations(){const d=aiOperationData();$('#ai-content').innerHTML=`<section class="panel ai-stats-toolbar" ${aiReq('operations.query')}><b>分析周期</b><select onchange="aiOperationRange=Number(this.value);aiQualityReport=null;aiOperations()"><option value="7" ${aiOperationRange===7?'selected':''}>近7日</option><option value="30" ${aiOperationRange===30?'selected':''}>近30日</option></select><span class="muted">${d.cutoff} 至 ${aiNow().slice(0,10)} · 区域全部搜索</span>${aiBtn('生成质量报告','aiGenerateQuality()','operations.report',true)}</section><div class="ai-metrics" ${aiReq('operations.metrics')}>${aiMetric('搜索量',d.searches,'周期内搜索请求次数')}${aiMetric('点击量',d.clicks,'产生结果点击的搜索请求数')}${aiMetric('无结果量',d.noresults,'正常返回但结果为0的请求')}${aiMetric('结果点击率',d.results?(d.clicks/d.results*100).toFixed(1)+'%':'0%','点击请求 / 有结果请求')}</div><section class="panel ai-section" ${aiReq('operations.funnel')}><h3>搜索漏斗分析</h3><div class="ais-funnel">${[['发起搜索',d.searches],['返回结果',d.results],['点击结果',d.clicks]].map(([name,v],i)=>`<div style="width:${100-i*15}%"><span>${name}</span><b>${v.toLocaleString()}</b><small>${d.searches?(v/d.searches*100).toFixed(1):'0'}%</small></div>`).join('')}</div><p class="muted">敏感词拦截 ${d.blocked} 次 · 无结果率 ${d.searches?(d.noresults/d.searches*100).toFixed(1):'0'}%</p></section><section class="panel ai-section" ${aiReq('operations.report')}><div class="ai-list-head"><h3>搜索质量报告</h3>${aiQualityReport?aiBtn('下载报告','aiDownloadQuality()','operations.report.download'):''}</div>${aiQualityReport?`<pre class="ais-code">${esc(aiQualityReport)}</pre>`:'<p class="muted">点击“生成质量报告”，自动汇总所选周期的搜索量、点击量、无结果量及搜索质量。</p>'}</section><section class="panel ai-section"><h3>统计口径</h3><p class="muted ais-footnote">搜索量按请求计数；有结果量排除无结果及敏感词拦截；点击量为至少点击一次结果的请求数，漏斗按去重请求统计。演示历史点击量按68%样例比例估算，新增详情点击加入统计。正式系统按搜索任务ID关联事件计算，聚合每日更新，进入或切换周期读取最新统计。</p></section>`;}
function aiGenerateQuality(){const d=aiOperationData();aiQualityReport=`搜索质量报告\n统计周期：${d.cutoff} 至 ${aiNow().slice(0,10)}（近${aiOperationRange}日）\n生成时间：${aiNow()}\n搜索量：${d.searches}\n有结果量：${d.results}\n点击量：${d.clicks}\n无结果量：${d.noresults}\n敏感词拦截：${d.blocked}\n无结果率：${d.searches?(d.noresults/d.searches*100).toFixed(1):0}%\n结果点击率：${d.results?(d.clicks/d.results*100).toFixed(1):0}%\n结论：${d.noresults?'存在无结果搜索词，可结合搜索记录核对数据覆盖与主题范围。':'当前周期未发现无结果搜索请求。'}\n说明：原型演示报告；历史点击数使用样例估算，正式系统应以埋点事件计算。`;aiOperations();toast('质量报告已自动生成');}
function aiDownloadQuality(){if(!aiQualityReport)return;const url=URL.createObjectURL(new Blob([aiQualityReport],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='搜索质量报告-'+aiNow().slice(0,10)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const aiRenderers={overview:aiOverview,themes:aiThemeList,tags:aiTagList,templates:aiTemplateList,sources:aiSourceList,indexes:aiIndexList,indexMonitor:aiIndexMonitor,search:aiSearchPage,recommendations:aiRecoPage,records:aiRecordPage,content:aiContentPage,operations:aiOperations};
if(section==='intelligent'||new URLSearchParams(location.search).get('system')==='intelligent'){aiOpen(new URLSearchParams(location.search).get('view')||'overview');}
